mapper.select:
select *from (
SELECT
a.*,
b.MACHINE_NAME
FROM
T_CD15_QUOTA_SETTING a
LEFT JOIN T_CD15_MACHINE_INFO b
ON a.MACHINE_ID = b.ID
WHERE
a.del_flag = '0'
and a.steel_strip_code = #{steelStripCode}

and a.machine_id = #{machineId}
and a.quota = #{quota}

    order by a.CREATE_TIME desc

) t

    order by ${orderStr}


where del_flag = '0'
and id != #{id}
and machine_id is null
and machine_id = #{machineId,jdbcType=DECIMAL}
and steel_strip_code is null
and steel_strip_code =
    #{steelStripCode,jdbcType=VARCHAR}

mapper.update:
merge into t_cd15_quota_setting a USING (
select #{QuotaSetting.steelStripCode,jdbcType=VARCHAR} steel_strip_code, #{QuotaSetting.machineId,jdbcType=DOUBLE} machine_id, #{QuotaSetting.quota,jdbcType=DOUBLE} quota, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.steel_strip_code is null and a.steel_strip_code is null) or (a.steel_strip_code = b.steel_strip_code)) and ((b.machine_id is null and a.machine_id is null) or(b.machine_id = a.machine_id)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.quota = b.quota, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.steel_strip_code, a.machine_id, a.quota, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.steel_strip_code, b.machine_id, b.quota, b.create_by, sysdate, b.remark, '0')
